//! `/data` on command storage against the transcript of the real vanilla server (`fixtures/data_commands_storage.golden`:
//! `### <command>` followed by the feedback lines, generated by feeding `data_commands_storage.cmds` to the vanilla
//! console on a fresh world; `System chat: ` prefixes stripped here).

use crate::command_common;

use mc_game::commands::{CommandSource, CommandSourceStack};
use mc_game::server::MinecraftServer;
use mc_text::Component;
use std::sync::{Arc, Mutex};

#[derive(Default)]
struct Capture(Mutex<Vec<String>>);

impl CommandSource for Capture {
    fn send_system_message(&self, message: &Component) {
        self.0.lock().unwrap().push(message.get_string());
    }
    fn accepts_success(&self) -> bool {
        true
    }
    fn accepts_failure(&self) -> bool {
        true
    }
    fn should_inform_admins(&self) -> bool {
        false
    }
}

fn run(server: &mut MinecraftServer, command: &str) -> Vec<String> {
    mc_game::commands::BrigadierExceptions::install();
    let capture = Arc::new(Capture::default());
    let source: CommandSourceStack = server
        .create_command_source_stack()
        .with_source(capture.clone());
    let commands = server.commands.clone();
    commands.perform_prefixed_command(server, source, command);
    capture.0.lock().unwrap().clone()
}

#[test]
fn data_storage_matches_vanilla_transcript() {
    let (mut server, _world) = command_common::test_server();
    let golden = include_str!("../fixtures/data_commands_storage.golden");
    let mut blocks: Vec<(&str, Vec<String>)> = Vec::new();
    for line in golden.lines() {
        if let Some(command) = line.strip_prefix("### ") {
            blocks.push((command, Vec::new()));
        } else if let Some((_, lines)) = blocks.last_mut() {
            lines.push(
                line.strip_prefix("System chat: ")
                    .unwrap_or(line)
                    .to_owned(),
            );
        }
    }
    assert!(blocks.len() > 100);
    for (command, expected) in blocks {
        assert_eq!(run(&mut server, command), expected, "`{command}`");
    }
}

/// The `data` subtree encodes to the bytes of the real vanilla `ClientboundCommandsPacket` at every permission level
/// (`fixtures/commands/CommandTreeGolden.java ... data`).
#[test]
fn data_tree_matches_vanilla() {
    use mc_game::commands::{CommandSourceStack, command_tree};
    use mc_game::server::permissions::{LevelBasedPermissionSet, PermissionLevel, PermissionSet};
    use mc_protocol::codec::{Decode, Encode};
    use mc_protocol::packets::play::ClientboundCommandsPacket;

    let commands = command_common::vanilla_commands();
    let subset_root = mc_brigadier::CommandNode::<CommandSourceStack>::new_root();
    for child in commands.get_dispatcher().get_root().get_children() {
        if child.get_name() == "data" {
            subset_root.add_child(child);
        }
    }
    let mut checked = 0;
    for line in include_str!("../fixtures/commands/data_tree_golden.txt").lines() {
        let mut it = line.split(' ');
        let (_, level, _, hex) = (
            it.next().unwrap(),
            it.next().unwrap(),
            it.next().unwrap(),
            it.next().unwrap(),
        );
        let bytes: Vec<u8> = (0..hex.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
            .collect();
        let permissions = PermissionSet::from(LevelBasedPermissionSet::for_level(
            PermissionLevel::by_id(level.parse().unwrap()),
        ));
        let root = command_tree::usable_root(
            &subset_root,
            &CommandSourceStack::compilation_context(permissions),
        );
        let mut out = Vec::new();
        command_tree::commands_packet(&root)
            .encode(&mut out)
            .unwrap();
        let ours = ClientboundCommandsPacket::decode(&mut out.as_slice()).unwrap();
        let theirs = ClientboundCommandsPacket::decode(&mut bytes.as_slice()).unwrap();
        for (i, (a, b)) in ours.entries.iter().zip(&theirs.entries).enumerate() {
            assert_eq!(a, b, "permission level {level}: node {i}");
        }
        assert_eq!(
            ours.entries.len(),
            theirs.entries.len(),
            "permission level {level}: node count"
        );
        assert_eq!(out, bytes, "permission level {level}");
        checked += 1;
    }
    assert_eq!(checked, 5);
}
